    internal static byte[] GetBytes()
    {
        using Stream? resource = typeof(JondoFixPayload).Assembly.GetManifestResourceStream(ResourceName);
        if (resource != null)
        {
            using var resourceDestination = new MemoryStream(ExpectedLength);
            resource.CopyTo(resourceDestination);
            byte[] resourceBytes = resourceDestination.ToArray();
            if (resourceBytes.Length != ExpectedLength)
                throw new InvalidDataException("The bundled JondoFix payload has an unexpected size.");
            return resourceBytes;
        }

        // Compatibility with development builds produced before the payload became an embedded
        // binary resource. Published launchers always use the resource above.
        byte[] compressed = Convert.FromBase64String(GzipBase64);
        using var source = new MemoryStream(compressed, writable: false);
        using var gzip = new GZipStream(source, CompressionMode.Decompress);
        using var destination = new MemoryStream(ExpectedLength);
        gzip.CopyTo(destination);
        byte[] result = destination.ToArray();
        if (result.Length != ExpectedLength)
            throw new InvalidDataException("The bundled JondoFix payload has an unexpected size.");
        return result;
    }
